  onDip:       'on_dip',
  beforeUse:   'before_use',
  afterUse:    'after_use',
  beforeDrink: 'before_drink',
  afterDrink:  'after_drink',
  beforeThrow: 'before_throw',
  afterThrow:  'after_throw',
};

/**
